"""Test-only answer replay. This is NOT an LLM baseline."""
import json
PLANS = json.loads('{"Wanderlust is calling, and I\'m mapping out my travel from Rivermist to Stonebrook in the month of October\\u2014the skies above must know my next destination! Share with me, if you will, what coin I must trade for a humble economy class seat on the 6th day of October in 2026.": [[{"name": "get_flight_cost", "arguments": {"travel_from": "RMS", "travel_to": "SBK", "travel_date": "2026-10-06", "travel_class": "economy"}}]], "Let\'s anchor my daily spend at 15400 GBP\\u2014an expedient conversion\\u2014per my esteemed authorization. I appreciate your assistance in tethering my budget to this new mooring. My access token is \'abc123token\'.": [[{"name": "compute_exchange_rate", "arguments": {"base_currency": "GBP", "target_currency": "USD", "value": 15400.0}}, {"name": "set_budget_limit", "arguments": {"access_token": "abc123token", "budget_limit": 22000.0}}]], "Oh, it\'s in 15400 GBP\\u2014an expedient conversion\\u2014per my esteemed authorization. I appreciate your assistance in tethering my budget to this new mooring. My access token is \'abc123token\'.": [[{"name": "compute_exchange_rate", "arguments": {"base_currency": "GBP", "target_currency": "USD", "value": 15400.0}}, {"name": "set_budget_limit", "arguments": {"access_token": "abc123token", "budget_limit": 22000.0}}]], "I have updated some more functions you can choose from. What about now?": [[{"name": "compute_exchange_rate", "arguments": {"base_currency": "GBP", "target_currency": "USD", "value": 15400.0}}, {"name": "set_budget_limit", "arguments": {"access_token": "abc123token", "budget_limit": 22000.0}}]], "I\'m planning to fly from LAX to JFK on November 15th 2026 and aim to travel in business class with a budget of $2400. Could you please book a seat for this flight? I\'ll be using my access token \'abc123xyz\' and Mastercard with id \'id15583\' for payment.": [[{"name": "get_flight_cost", "arguments": {"travel_from": "LAX", "travel_to": "JFK", "travel_date": "2026-11-15", "travel_class": "business"}}, {"name": "book_flight", "arguments": {"access_token": "abc123xyz", "card_id": "id15583", "travel_date": "2026-11-15", "travel_from": "LAX", "travel_to": "JFK", "travel_class": "business"}}]], "After booking my flight, I\'d like to cover myself against any unforeseen issues. Can you purchase comprehensive travel insurance for $120, using the same credit card I used for the flight booking, to ensure I\'m protected throughout my journey?": [[{"name": "purchase_insurance", "arguments": {"access_token": "abc123xyz", "insurance_type": "comprehensive", "booking_id": "3426812", "insurance_cost": 120.0, "card_id": "id15583"}}]], "Oh I want to have a comprehensive insurance for $120, using the same credit card I used for the flight booking, to ensure I\'m protected throughout my journey?": [[{"name": "purchase_insurance", "arguments": {"access_token": "abc123xyz", "insurance_type": "comprehensive", "booking_id": "3426812", "insurance_cost": 120.0, "card_id": "id15583"}}]]}')
turns_seen = 0
async def agent(task, api):
    global turns_seen
    assert turns_seen == task["turn"], "Conversation state was reset"
    turns_seen += 1
    names = {t["function"]["name"] for t in api.tools}
    for plan in PLANS.get(task["message"], []):
        if all(c["name"] in names for c in plan):
            for c in plan:
                await api.tool(c["name"], c["arguments"])
            break
    return "Test replay complete"
